 return <div ref={mountRef} data-streetverse-world-root="true" style={{position:'fixed',inset:0,background:'#07101d',overflow:'hidden'}}><div style={{position:'fixed',top:'max(10px,env(safe-area-inset-top))',left:'50%',transform:'translateX(-50%)',zIndex:41000,padding:'7px 10px',borderRadius:999,background:'#063b2bee',border:'1px solid #63f0c0aa',color:'#fff',font:'950 10px system-ui',pointerEvents:'none'}}>3D MOBILE • CLEAN CONTROL</div><button aria-label="Open Holo FON" onClick={()=>openShell('holofon')} style={{position:'fixed',top:'max(12px,calc(env(safe-area-inset-top) + 12px))',right:'max(14px,calc(env(safe-area-inset-right) + 14px))',zIndex:41010,width:48,height:48,borderRadius:24,border:'2px solid #69e9ff',background:'#061826ee',color:'#fff',fontSize:23,boxShadow:'0 0 16px #00d9ff66',touchAction:'manipulation'}}>📱</button><button aria-label="Open StreetVerse quick menu" aria-expanded={menuOpen} onClick={()=>setMenuOpen(v=>!v)} style={{position:'fixed',top:'max(12px,calc(env(safe-area-inset-top) + 12px))',right:'max(70px,calc(env(safe-area-inset-right) + 70px))',zIndex:41010,width:48,height:48,borderRadius:24,border:'2px solid #78ffb4',background:'#071c17ee',color:'#fff',fontSize:24,fontWeight:950,boxShadow:'0 0 16px #39ff9a44',touchAction:'manipulation'}}>⋯</button>{menuOpen&&<div role="menu" aria-label="StreetVerse quick navigation" style={{position:'fixed',top:'max(68px,calc(env(safe-area-inset-top) + 68px))',right:'max(12px,calc(env(safe-area-inset-right) + 12px))',zIndex:42000,width:184,padding:9,borderRadius:16,border:'1px solid #69e9ff88',background:'rgba(3,13,22,.95)',boxShadow:'0 18px 46px #000c',display:'grid',gap:7}}>{([['sparrow','🗺 SCAN MAP'],['holoverse','🌐 HOLOVERSE'],['carousel','✦ ALL VERSES'],['faithverse','📖 FAITHVERSE'],['home','⌂ HOME']] as const).map(([target,label])=><button key={target} role="menuitem" onClick={()=>quickAction(target)} style={{minHeight:44,borderRadius:11,border:'1px solid #27485c',background:'#091923',color:'#fff',font:'900 11px system-ui',textAlign:'left',padding:'10px 12px',touchAction:'manipulation'}}>{label}</button>)}</div>}{missionGuide&&<button aria-live="polite" aria-label={`Start or focus mission ${missionGuide.label}`} onClick={()=>{const detail={missionId:missionGuide.id,id:missionGuide.id,title:missionGuide.label,objective:'Reach the highlighted StreetVerse mission marker.',source:'streetverse-mobile-world-marker'};window.dispatchEvent(new CustomEvent('tryamm:streetverse-mission-start',{detail}));window.dispatchEvent(new CustomEvent('tryamm:city-navigation-target',{detail:{type:'mission',missionId:missionGuide.id,label:missionGuide.label}}));setMessage(`MISSION ACTIVE • ${missionGuide.label} • follow the gold marker.`)}} style={{position:'fixed',left:'50%',transform:'translateX(-50%)',top:'max(88px,calc(env(safe-area-inset-top) + 80px))',zIndex:33500,minWidth:190,maxWidth:'78vw',padding:'9px 13px',borderRadius:14,border:'1px solid #f5d56baa',background:'rgba(8,14,22,.92)',color:'#fff',boxShadow:'0 0 20px #ffd65a33',pointerEvents:'auto',textAlign:'center',font:'900 11px system-ui',touchAction:'manipulation'}}><span style={{color:'#ffe47f'}}>MISSION • {missionGuide.label}</span><span style={{display:'block',marginTop:3,fontSize:10,opacity:.9}}>{missionGuide.distance}m • {missionGuide.bearing}</span><span style={{display:'block',marginTop:4,fontSize:9,color:'#8effb7'}}>TAP TO START / FOCUS</span></button>}{interactionPrompt&&<button aria-label={`${interactionPrompt.action} ${interactionPrompt.label}`} onClick={activateContextPrompt} style={{position:'fixed',right:'max(18px, env(safe-area-inset-right))',bottom:'max(28px, env(safe-area-inset-bottom))',zIndex:34000,minWidth:148,maxWidth:190,minHeight:58,padding:'9px 12px',borderRadius:16,border:'2px solid #7be9ff',background:'rgba(3,18,29,.92)',color:'#fff',boxShadow:'0 0 22px #00d9ff55',font:'900 11px system-ui',touchAction:'manipulation',textAlign:'center'}}><span style={{display:'block',fontSize:12,color:'#9ef1ff'}}>{interactionPrompt.action}</span><span style={{display:'block',marginTop:3,fontSize:9,opacity:.8}}>{interactionPrompt.label}</span></button>}<div aria-label="StreetVerse analog joystick" onPointerDown={e=>{e.currentTarget.setPointerCapture(e.pointerId);joystick(e)}} onPointerMove={e=>{if(e.currentTarget.hasPointerCapture(e.pointerId))joystick(e)}} onPointerUp={stopJoystick} onPointerCancel={stopJoystick} onLostPointerCapture={stopJoystick} style={{position:'fixed',left:'max(18px, env(safe-area-inset-left))',bottom:'max(22px, env(safe-area-inset-bottom))',zIndex:33000,width:118,height:118,borderRadius:'50%',border:'2px solid #7be9ff',background:'rgba(2,12,22,.68)',boxShadow:'0 0 22px #00d9ff55',pointerEvents:'auto',touchAction:'none',display:'grid',placeItems:'center'}}><div ref={joystickKnobRef} style={{width:52,height:52,borderRadius:'50%',background:'rgba(123,233,255,.72)',border:'2px solid #dffaff',pointerEvents:'none',transition:'transform 45ms linear',willChange:'transform'}}/></div><div style={{position:'fixed',left:'max(8px, env(safe-area-inset-left))',top:'max(8px, env(safe-area-inset-top))',zIndex:17020,display:'flex',gap:6,alignItems:'center',pointerEvents:'none',font:'800 10px system-ui'}}><div style={{padding:'6px 8px',borderRadius:999,background:'rgba(3,12,20,.72)',border:'1px solid #5be7ff66',color:'#fff'}}>{status.replace('MOBILE CITY • ','')}</div><div aria-live="polite" style={{padding:'6px 8px',borderRadius:999,background:'rgba(3,12,20,.72)',border:'1px solid #5be7ff66',color:'#9ee8ff'}}>{weatherStatus}</div><button aria-label="Exit StreetVerse" onClick={onClose} style={{pointerEvents:'auto',minWidth:44,minHeight:44,borderRadius:999,border:'1px solid #ffffff33',background:'rgba(18,25,35,.78)',color:'#fff',fontWeight:900}}>×</button></div><div aria-live="polite" style={{position:'fixed',left:8,right:8,top:'max(58px, calc(env(safe-area-inset-top) + 50px))',zIndex:17010,textAlign:'center',pointerEvents:'none',color:'#dffaff',font:'700 10px system-ui',textShadow:'0 1px 4px #000'}}>{(message.includes('No drivable')||message.includes('REPAIR'))?message:''}</div></div>
